test("a 10% coupon lowers 200 to 180", () => {
	// Arrange: prepare the situation
	const cart = new Cart([{ price: 200 }]);
	// Act: do the one thing being tested
	const total = cart.totalWith("TEN");
	// Assert: compare with what we expect
	expect(total).toBe(180);
});

const cart: string[] = [];          // shared by every test

test("adds an item", () => {
	cart.push("book");
	expect(cart.length).toBe(1);
});
test("adds a second item", () => {
	cart.push("pen");
	expect(cart.length).toBe(2);   // passes only if the first test ran before
});

